pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // Helper contract that will always return true on transferFrom
    contract Helper {
        function transferFrom(address, address, uint256) external pure returns (bool) {
            return true;
        }
    }

    function setUp() public {
        c = new C();
    }

    function testRegression_property() public {
        // Deploy helper contract
        Helper helper = new Helper();

        // Prepare addresses
        address from = address(0x1111);
        address[] memory tos = new address[](1);
        tos[0] = address(0x2222);
        uint256 value = 100;

        // Call transfer - this should NOT revert for reference (C), but WILL revert for mutant
        vm.prank(from);
        bool ok;
        try c.transfer(from, address(helper), tos, value) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference contract should return true (ok = true), mutant reverts (ok = false)
        assertTrue(ok, "Reference should succeed, mutant should revert");
    }
}

