// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Helper token contract that counts transferFrom calls
    address token;
    function deployToken() internal returns (address) {
        // Deploy a simple token that counts calls
        bytes memory code = type(CounterToken).creationCode;
        address addr;
        assembly { addr := create(0, add(code, 0x20), mload(code)) }
        return addr;
    }

    function testRegression_property() public {
        token = deployToken();
        CounterToken(token).setCounter(5);

        address[] memory tos = new address[](2);
        tos[0] = address(this);
        tos[1] = address(0x02);

        // All transfers succeed
        vm.prank(address(this));
        bool success = c.transfer(address(this), token, tos, 1);
        assertTrue(success);
        // Reference called 2 times, buggy called 1 time
        uint256 count = CounterToken(token).getCounter();
        assertTrue(count == 4, "Expected counter = 4 (2 calls made, so 5-2=3 for ref? Actually ref calls 2 times => 5-2=3, bug calls 1 => 4. Assert that bug would give 4)");
    }
}

contract CounterToken {
    uint256 public counter;
    function setCounter(uint256 _c) public { counter = _c; }
    function transferFrom(address, address, uint256) public returns (bool) { counter--; return true; }
    function getCounter() public view returns (uint256) { return counter; }
}
